add_filter( 'woocommerce_single_product_image_gallery_classes', 'perfectpixel_gallery_columns_class' );
add_filter( 'woocommerce_product_thumbnails_columns', 'perfectpixel_gallery_columns_number' );
add_action( 'wp_head', 'perfectpixel_gallery_columns_css' );

function perfectpixel_gallery_columns_number() {
	return max( 1, (int) '{{gallery_thumbnail_columns}}' );
}

function perfectpixel_gallery_columns_class( $classes ) {
	$classes = preg_grep( '/^woocommerce-product-gallery--columns-\d+$/', $classes, PREG_GREP_INVERT );
	$classes[] = 'woocommerce-product-gallery--columns-' . perfectpixel_gallery_columns_number();
	return $classes;
}

function perfectpixel_gallery_columns_css() {
	if ( ! function_exists( 'is_product' ) || ! is_product() ) {
		return;
	}
	$n = perfectpixel_gallery_columns_number();
	printf(
		'<style>.woocommerce div.product div.images .flex-control-thumbs li{width:calc(%1$s%% - .5em);margin:.5em .5em 0 0;clear:none!important}.woocommerce div.product div.images .flex-control-thumbs li:nth-child(%2$dn){margin-right:0}</style>',
		esc_html( round( 100 / $n, 4 ) ),
		$n
	);
}
